async fn dav_calendar_home(
    State(accounts): State<CaldavAccountService>,
    Path(principal_id): Path<String>,
    request: Request,
) -> Response {
    match request.method().as_str() {
        OPTIONS => dav_capabilities(),
        PROPFIND => {
            let Some(authorization) = request.headers().get(header::AUTHORIZATION) else {
                return dav_unauthorized();
            };
            let Ok(session) = accounts.authenticate(authorization).await else {
                return dav_unauthorized();
            };
            let Ok(depth) = parse_depth(request.headers()) else {
                return dav_bad_depth();
            };
            let principal = match accounts.resolve_principal(&principal_id).await {
                Ok(Some(principal)) => principal,
                Ok(None) => return dav_not_found(),
                Err(_) => return dav_server_error(),
            };
            if principal.user_id != session.user_id {
                return dav_not_found();
            }
            let Ok(calendars) = accounts.list_calendars(session.user_id).await else {
                return dav_server_error();
            };
            render_calendar_home(&accounts, &principal_id, &principal, &calendars, depth)
        }
        _ => method_not_allowed(),
    }
}

async fn dav_calendar(
    State(accounts): State<CaldavAccountService>,
    Path((principal_id, calendar_key)): Path<(String, String)>,
    request: Request,
) -> Response {
    match request.method().as_str() {
        OPTIONS => dav_capabilities(),
        PROPFIND => {
            let Some(authorization) = request.headers().get(header::AUTHORIZATION) else {
                return dav_unauthorized();
            };
            let Ok(session) = accounts.authenticate(authorization).await else {
                return dav_unauthorized();
            };
            let Ok(depth) = parse_depth(request.headers()) else {
                return dav_bad_depth();
            };
            let principal = match accounts.resolve_principal(&principal_id).await {
                Ok(Some(principal)) => principal,
                Ok(None) => return dav_not_found(),
                Err(_) => return dav_server_error(),
            };
            if principal.user_id != session.user_id {
                return dav_not_found();
            }
            let Ok(calendar_id) = calendar_key.parse::<i64>() else {
                return dav_calendar_not_found();
            };
            let Some(calendar) = accounts
                .resolve_calendar(session.user_id, calendar_id)
                .await
                .unwrap_or(None)
            else {
                return dav_calendar_not_found();
            };
            render_calendar(&accounts, &principal_id, &calendar, depth)
        }
        _ => method_not_allowed(),
    }
}

