enum DavDepth {
    Zero,
    One,
}

fn parse_depth(headers: &axum::http::HeaderMap) -> Option<DavDepth> {
    let value = headers.get("depth").and_then(|value| value.to_str().ok())?;
    if value.eq_ignore_ascii_case("0") {
        Some(DavDepth::Zero)
    } else if value.eq_ignore_ascii_case("1") {
        Some(DavDepth::One)
    } else {
        None
    }
}

